private function roundHalfUp(string $value, int $precision): string
{
    // Use a small epsilon to handle bcmath precision issues with float conversion if any,
    // but we are using strings, so it should be fine.

    $multiplier = pow(10, $precision);
    $shifted = bcmul($value, (string)$multiplier, 16);

    $split = explode('.', $shifted);
    $intPart = $split[0];
    $fracPart = $split[1] ?? '0';

    // Check the first digit after the decimal point for half-up rounding
    $firstDigit = (int)($fracPart[0] ?? 0);
    if ($firstDigit >= 5) {
        $intPart = bcadd($intPart, '1', 0);
    }

    return bcdiv($intPart, (string)$multiplier, $precision);
}

